DROP TABLE IF EXISTS `expense_engineer_attendance`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `expense_engineer_attendance` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  `record_date` date NOT NULL COMMENT '日期',
  `person_name` varchar(50) NOT NULL COMMENT '填写人',
  `test_task` varchar(50) DEFAULT NULL COMMENT '试验任务: 行车/泊车/用例点检/车辆整备',
  `car_number` varchar(200) DEFAULT NULL COMMENT '车辆编号',
  `start_time` time(6) DEFAULT NULL COMMENT '上班时间',
  `end_time` time(6) DEFAULT NULL COMMENT '下班时间',
  `is_overtime` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否加班',
  `overtime_hours` decimal(4,1) NOT NULL DEFAULT '0.0' COMMENT '加班时长(h)',
  `work_duration` decimal(4,1) NOT NULL DEFAULT '0.0' COMMENT '工作日时长(h)',
  `total_hours` decimal(4,1) NOT NULL DEFAULT '0.0' COMMENT '当天总工时(h)',
  `travel_status` varchar(50) DEFAULT NULL COMMENT '出差状态',
  `work_location` varchar(200) DEFAULT NULL COMMENT '工作地点',
  `location_coords` varchar(100) DEFAULT NULL COMMENT '定位位置',
  `workload` varchar(500) DEFAULT NULL COMMENT '当天工作量(次/km)',
  `problems_found` int NOT NULL DEFAULT '0' COMMENT '行车泊车发现问题数',
  `check_cases` int NOT NULL DEFAULT '0' COMMENT '点检用例数',
  `software_flash_count` int NOT NULL DEFAULT '0' COMMENT '整备车辆刷写软件数量',
  `approver1` varchar(50) DEFAULT NULL COMMENT '审批人1',
  `approver1_result` varchar(20) DEFAULT NULL COMMENT '审批人1审核结果',
  `approver2` varchar(50) DEFAULT NULL COMMENT '审批人2',
  `approver2_result` varchar(20) DEFAULT NULL COMMENT '审批人2审核结果',
  `issue_detail` longtext COMMENT '问题明细',
  `test_version` varchar(100) DEFAULT NULL COMMENT '试验版本',
  `attachment_url` varchar(500) DEFAULT NULL COMMENT '考勤打卡附件',
  `approve_type` varchar(50) DEFAULT NULL COMMENT '审批类型',
  `task_status` varchar(50) DEFAULT NULL COMMENT '任务单状态',
  `project_id` bigint NOT NULL COMMENT '所属项目',
  `test_order_id` bigint DEFAULT NULL COMMENT '试验单号',
  `requirement_code` varchar(100) DEFAULT NULL COMMENT '试验需求编号',
  PRIMARY KEY (`id`),
  KEY `fk_expense__expense__a187555b` (`project_id`),
  KEY `fk_expense__expense__c88d2e56` (`test_order_id`),
  KEY `idx_expense_eng_created_670928` (`created_at`),
  KEY `idx_expense_eng_updated_99eaf7` (`updated_at`),
  KEY `idx_expense_eng_record__136582` (`record_date`),
  CONSTRAINT `fk_expense__expense__a187555b` FOREIGN KEY (`project_id`) REFERENCES `expense_project` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_expense__expense__c88d2e56` FOREIGN KEY (`test_order_id`) REFERENCES `expense_test_order` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6013 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='工程师考勤打卡';
/*!40101 SET character_set_client = @saved_cs_client */;

